components.css:
.ds-btn { background: #3C3C3C; color: #B4B4B4; font: 300 13px 'Ubuntu Light', system-ui, sans-serif; padding: 6px 10px; border: 0; border-radius: 6px; cursor: pointer; transition: background .2s ease, color .2s ease; }
.ds-btn:hover { background: rgba(34,211,238,.16); color: #F0F0F0; outline: 1.5px solid #969696; }
.ds-btn:focus-visible { outline: 2px solid #22D3EE; outline-offset: 1px; }
.ds-btn:active { background: rgba(34,211,238,.27); color: #FFFFFF; outline: 2px solid #FFFFFF; }
.ds-btn:disabled { opacity: .5; cursor: default; }

.ds-toggle { background: #3C3C3C; color: #B4B4B4; font: 300 13px 'Ubuntu Light', system-ui, sans-serif; padding: 6px 10px; border: 0; border-radius: 6px; cursor: pointer; transition: background .2s ease, color .2s ease; }
.ds-toggle:hover { background: rgba(34,211,238,.16); color: #F0F0F0; }
.ds-toggle:focus-visible { outline: 2px solid #22D3EE; outline-offset: 1px; }
.ds-toggle[aria-pressed="true"] { background: #22D3EE; color: #020617; }
.ds-toggle[aria-pressed="true"]:hover { background: #22D3EE; color: #020617; }

.ds-field { background: #020617; color: #8C8C8C; font: 300 13px 'Ubuntu Light', system-ui, sans-serif; padding: 6px 10px; width: 280px; max-width: 100%; border: 1px solid #334155; border-radius: 6px; }
.ds-field::placeholder { color: #8C8C8C; opacity: .6; }
.ds-field:focus { outline: none; border-color: #22D3EE; }
.ds-field::selection { background: #22D3EE; color: #020617; }
.ds-field:disabled { opacity: .5; }

.ds-island { background: #0F172A; color: #8C8C8C; font: 300 13px 'Ubuntu Light', system-ui, sans-serif; border: 1px solid #334155; border-radius: 8px; padding: 6px; box-shadow: 10px 20px 15px rgba(0,0,0,.376); max-width: 420px; }
.ds-island-title { margin: 0 0 8px; font-size: 18px; font-weight: 300; color: #8C8C8C; }
.ds-island-body { margin: 0 0 8px; line-height: 1.4; }
.ds-island:focus-within { border-color: #334155; }

.ds-toolbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; background: #0F172A; color: #8C8C8C; font: 300 13px 'Ubuntu Light', system-ui, sans-serif; padding: 6px 10px; border-radius: 0; border-bottom: 1px solid #334155; }
.ds-toolbar-toggle { border-radius: 6px; }
.ds-toolbar-clock { margin-left: auto; font-variant-numeric: tabular-nums; }

.ds-status { margin: 0 0 8px; font: 300 13px 'Ubuntu Light', system-ui, sans-serif; color: #808080; }
.ds-status-ok { color: #4ADE80; }
.ds-status-warn { color: #FABF69; }
.ds-status-fail { color: #F87171; }
.ds-status-idle { color: #808080; }

.ds-marker { display: inline-flex; align-items: center; gap: 6px; font: 300 12px 'Ubuntu Light', system-ui, sans-serif; color: #E2E8F0; }
.ds-marker-dot { width: 16px; height: 16px; border-radius: 50%; background: #2563EB; border: 2px solid #FFFFFF; box-sizing: border-box; box-shadow: 0 0 0 4px transparent; }
.ds-marker-follow { box-shadow: 0 0 0 4px rgba(255,255,255,0), 0 0 0 6px #FFFF00; }
.ds-marker-stale .ds-marker-dot { background: #808080; }
.ds-marker:focus-visible { outline: none; }
